        break;
    case 4:   // 离开 PVP
        *(int*)((char*)addr_8F8528 + 2484) = 0;
        engine_log("@@UDP STOP - onChangeModule(), MODULE_TYPE_PVP 1");
        vcall(addr_8F8520, 152);          // 停 UDP
