                sub_4461F0(addr_8F8520);
                sub_45B0A0(*(int*)(this + 20));
                sub_425960(0,
                           *(int*)(*(int*)(*(int*)(this + 20) + 44) + 44),
                           *(int*)(*(int*)(*(int*)(this + 20) + 44) + 104));
                vcall(addr_8F8520, 164);
                sub_458400(*(void**)((char*)addr_8F8528 + 2436));
